export function getNumberData(number) {
    const key = String(number);
    return NUMBERS_DB[key] || {
        core: 'Значение этого числа будет добавлено позже.',
        personality: 'Значение этого числа будет добавлено позже.',
        energy: 'Значение этого числа будет добавлено позже.',
        earth: 'Значение этого числа будет добавлено позже.',
        money: 'Значение этого числа будет добавлено позже.',
        mission: 'Значение этого числа будет добавлено позже.',
        minus: 'Значение этого числа будет добавлено позже.'
    };
}

export function getNumberDataDate(number) {
    const key = String(number);
    return NUMBERS_DB_DATE[key] || {
        title: 'ЗНАЧЕНИЕ БУДЕТ ДОБАВЛЕНО',
        core: 'Значение для даты будет добавлено позже.',
        strength: 'Значение для даты будет добавлено позже.',
        task: 'Значение для даты будет добавлено позже.',
        money: 'Значение для даты будет добавлено позже.',
        minus: 'Значение для даты будет добавлено позже.',
        main_task: 'Значение для даты будет добавлено позже.'
    };
}

export function getAllNumbers() {
    return Object.keys(NUMBERS_DB).map(Number).sort((a, b) => a - b);
}